input.command:
mkdir -p /tmp/lamp-8-scratch && cat > /tmp/lamp-8-scratch/probe.mjs <<'EOF'
// Scratch probe: ceiling above Restroom A, and a hanging-lantern variant for comparison.
import { load, Grid } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const src = process.argv[2];
const out = process.argv[3];
const g = load(src);
for (let y = 6; y <= 9; y++) {
  const row = [];
  for (let z = 24; z <= 29; z++) {
    const cs = [25, 26].map((x) => {
      const c = g.get(x, y, z);
      return c ? String(c[0] ?? c.block ?? c).replace("minecraft:", "") : "air";
    });
    row.push(`z${z}:${cs.join("/")}`);
  }
  console.log(`y${y}  ${row.join("  ")}`);
}
if (out) {
  // Variant: the standing lantern on the barrel moves to a hanging lantern under the roof deck at y8.
  g.set(26, 2, 25, "air");
  g.set(26, 7, 25, "lantern", { hanging: "true" });
  g.save(out);
  console.log("variant saved", out);
}
EOF
cd /Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/gas-station/crew/lamp-8 && node /tmp/lamp-8-scratch/probe.mjs build.nbt /tmp/lamp-8-scratch/hanging.nbt

